import re
from auto_config.generator.gnb.managed_objects.managed_object import ManagedObject


class SmodParamsGenerator(ManagedObject):

    def _prepare_section_content(self, execution_config, *args, **kwargs):
        smod_ent = self.enb_ent_config['smods'][self.mo_num]
        smod_num = int(re.search(r'SMOD-(\d+)', self.dist_name).group(1))
        num_smods = len(self.enb_ent_config.get('smods', {}))

        if num_smods == 2:
            enb_num = self.enb_ent_config['num']
            smods = self.enb_ent_config.get('smods', {})
            positionInSubrack = self._get_position_in_subrack(enb_num, smods, smod_num)
            self.set_parameter('positionInSubrack', positionInSubrack)

        self.set_parameter('prodCodePlanned', smod_ent['prod_code_planned'])

    def _get_position_in_subrack(self, enb_num, smods, smod_id):
        side_key = {'left': 'LeftSide', 'right': 'RightSide'}
        smod1_side_string = self._get_position_in_subrack_from_enb(smods.get('1', '')['side'])
        smod2_side_string = self._get_position_in_subrack_from_enb(smods.get('2', '')['side'])

        if not smod1_side_string:
            smod1_side_string = "left" if int(enb_num) % 2 == 0 else "right"
        if not smod2_side_string:
            smod2_side_string = "right" if int(enb_num) % 2 == 0 else "left"

        return [side_key[smod1_side_string], side_key[smod2_side_string]][smod_id - 1]

    @staticmethod
    def _get_position_in_subrack_from_enb(smod_side):
        side = re.match(r'(left|right)', smod_side, re.I)
        return side.group(1) if side else ''
